describe('AC-9: notchCalculator over all 361 ordered pairs', () => {
  test('AC-9: shape, sign, direction and WL thresholds hold for every pair; totals match the oracle', () => {
    const dir = { downgrade: 0, upgrade: 0, unchanged: 0 };
    const wlCount = { 0: 0, 1: 0, 2: 0 };
    let pairs = 0;

    for (const p of RATING_SCALE) {
      for (const c of RATING_SCALE) {
        pairs += 1;
        const r = notchCalculator(p, c);
        const label = `(${p},${c})`;

        assert.ok(!(r instanceof Promise), `${label} must not be a Promise`);
        assert.equal(typeof r?.then, 'undefined', `${label} must not be thenable`);
        assert.strictEqual(Object.getPrototypeOf(r), Object.prototype, `${label} plain object`);
        assert.deepStrictEqual(Object.keys(r).sort(), ['direction', 'notches', 'wl'], `${label} keys`);

        const n = notchChange(p, c);
        assert.ok(Number.isInteger(r.notches), `${label} integer notches`);
        assert.strictEqual(r.notches, n, `${label} notches === notchChange`);
        assert.strictEqual(
          n,
          RATING_SCALE.indexOf(c) - RATING_SCALE.indexOf(p),
          `${label} equals scale position difference`,
        );

        const expectedDir = n > 0 ? 'downgrade' : n < 0 ? 'upgrade' : 'unchanged';
        assert.strictEqual(r.direction, expectedDir, `${label} direction`);

        const expectedWl = n <= 1 ? 0 : n === 2 ? 1 : 2;
        assert.strictEqual(r.wl, expectedWl, `${label} wl`);

        dir[r.direction] += 1;
        wlCount[r.wl] += 1;
      }
    }

    assert.equal(pairs, 361);
    assert.deepStrictEqual(dir, { downgrade: 171, upgrade: 171, unchanged: 19 });
    assert.deepStrictEqual(wlCount, { 0: 208, 1: 17, 2: 136 });
  });

  test('AC-9: WL boundary steps: notches 1 -> 0, 2 -> 1, 3 -> 2, 18 -> 2, negative -> 0', () => {
    assert.strictEqual(notchCalculator('AAA', 'AA+').wl, 0);
    assert.strictEqual(notchCalculator('AAA', 'AA').wl, 1);
    assert.strictEqual(notchCalculator('AAA', 'AA-').wl, 2);
    assert.strictEqual(notchCalculator('AAA', 'CCC-').wl, 2);
    assert.strictEqual(notchCalculator('CCC-', 'AAA').wl, 0);
  });
});

describe('No side effects', () => {
  test('calls leave RATING_SCALE intact and return separate, deep-equal objects', () => {
    const a = notchCalculator('BBB+', 'BB+');
    const b = notchCalculator('BBB+', 'BB+');
    assert.notStrictEqual(a, b);
    assert.deepStrictEqual(a, b);
    a.wl = 99;
    assert.strictEqual(notchCalculator('BBB+', 'BB+').wl, 2);
    assert.deepStrictEqual(RATING_SCALE, EXPECTED_SCALE);
    assert.equal(Object.isFrozen(RATING_SCALE), true);
  });

  test('notchChange is deterministic across repeated calls', () => {
    assert.strictEqual(notchChange('BBB+', 'BB+'), notchChange('BBB+', 'BB+'));
  });
});

