/**
 * The 19 C1 credit ratings, best first (index 0 is `AAA`, index 18 is `CCC-`).
 * The array is frozen: mutating it throws `TypeError` in strict mode.
 *
 * @type {readonly string[]}
 */
export const RATING_SCALE = Object.freeze([
  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-',
  'BBB+', 'BBB', 'BBB-', 'BB+', 'BB', 'BB-',
  'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-',
]);

/**
 * Turns a rating argument into its position on {@link RATING_SCALE}.
 * Only strings are accepted (no type conversion); the value is trimmed with
 * `String.prototype.trim` and matched case-insensitively.
 *
 * @param {string} name Argument name, used in the error message.
 * @param {unknown} value The raw argument.
 * @returns {number} Index into RATING_SCALE.
 * @throws {RangeError} If the value is not a string or not one of the 19 ratings.
 */
function positionOf(name, value) {
  if (typeof value !== 'string') {
    throw new RangeError(
      `${name}: expected a rating string, got ${typeof value} (${describe(value)})`,
    );
  }
  const index = RATING_SCALE.indexOf(value.trim().toUpperCase());
  if (index === -1) {
    throw new RangeError(`${name}: unknown rating ${JSON.stringify(value)}`);
  }
  return index;
}

/**
 * Renders a non-string value for an error message without throwing.
 *
 * @param {unknown} value
 * @returns {string}
 */
function describe(value) {
  try {
    return String(JSON.stringify(value));
  } catch {
    return 'unprintable';
  }
}

/**
 * Number of notches between two ratings: position(current) - position(previous).
 * Positive is a downgrade, negative an upgrade, 0 unchanged (never `-0`).
 *
 * @param {string} previous Previous rating (a rating string, trimmed, case-insensitive).
 * @param {string} current Current rating (a rating string, trimmed, case-insensitive).
 * @returns {number} Signed integer notch change; positive = downgrade, negative = upgrade.
 * @throws {RangeError} If either argument is not a string or not one of the 19 ratings.
 */
export function notchChange(previous, current) {
  const from = positionOf('previous', previous);
  const to = positionOf('current', current);
  // `+ 0` turns a possible -0 into +0.
  return to - from + 0;
}

/**
 * Scores a rating move: signed notches, direction and the Watchlist level
 * (Indicator 13).
 *
 * Sign convention: positive notches are a downgrade, negative an upgrade.
 * WL thresholds: notches <= 1 -> 0, notches === 2 -> 1, notches >= 3 -> 2.
 *
 * @param {string} previous Previous rating (a rating string, trimmed, case-insensitive).
 * @param {string} current Current rating (a rating string, trimmed, case-insensitive).
 * @returns {{notches: number, direction: 'downgrade' | 'upgrade' | 'unchanged', wl: 0 | 1 | 2}}
 *   A new plain object; `notches` equals `notchChange(previous, current)`.
