    assert.strictEqual(notchCalculator('A', 'A-').wl, 0);
    assert.strictEqual(countryRatingChangeWl('A', 'A-'), 1);
  });

  test('AC-12 (C6): over all 361 pairs the two WLs differ only when d === 1', () => {
    let differing = 0;
    for (const p of RATING_SCALE) {
      for (const c of RATING_SCALE) {
        const d = notchChange(p, c);
        const calc = notchCalculator(p, c).wl;
