+import { notchChange } from '../ratings/notch.mjs';
+
+/**
+ * Indicator 12 (REQ-03-12): Watchlist level for a country rating change.
+ *
+ * Takes `d = notchChange(previous, current)` (positive = downgrade,
+ * negative = upgrade) and maps it to a WL:
+ * `d <= 0` -> 0, `d === 1` -> 1, `d >= 2` -> 2.
+ *
+ * Note (C6): a 1-notch downgrade scores 1 here, whereas `notchCalculator`
+ * (Indicator 13) scores it 0. The difference is intended.
+ *
+ * @param {string} previous Previous country rating (a rating string, trimmed, case-insensitive).
+ * @param {string} current Current country rating (a rating string, trimmed, case-insensitive).
+ * @returns {0 | 1 | 2} The Watchlist level: 0 for no change or an upgrade, 1 for a
+ *   1-notch downgrade, 2 for a downgrade of 2 or more notches.
+ * @throws {RangeError} If either argument is not a string or not one of the 19
+ *   ratings; the error comes unchanged from `notchChange`.
+ */
+export function countryRatingChangeWl(previous, current) {
+  const d = notchChange(previous, current);
+  if (d <= 0) return 0;
+  if (d === 1) return 1;
+  return 2;
+}
